package br.com.erombox.nativeapp;

import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.content.*;
import android.text.InputType;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.*;
import org.json.*;

public class MainActivity extends Activity {
  private LinearLayout root, content;
  private EditText titleField, bodyField, searchField;
  private final int bg=Color.rgb(9,10,14), panel=Color.rgb(18,21,30), white=Color.rgb(245,246,250), muted=Color.rgb(160,166,181), accent=Color.rgb(91,163,255), border=Color.rgb(42,46,58);
  private final ArrayList<Note> notes=new ArrayList<>();
  private String filter="";
  private int nextId=1;
  private static class Note { int id; String title,body,updated; Note(int i,String t,String b,String u){id=i;title=t;body=b;updated=u;} }
  @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);load();if(getPreferences(0).getBoolean("local_account",false))showNotes();else showLogin();}
  private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
  private void shell(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(22),dp(22),dp(14));root.setBackgroundColor(bg);setContentView(root);TextView h=text(title,28,true,white);root.addView(h);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(1);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
  private TextView text(String s,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(6),0,dp(6));return t;}
  private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(primary?Color.rgb(6,18,35):white);b.setTextSize(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(primary?accent:Color.rgb(26,29,39)));b.setMinHeight(dp(54));b.setPadding(dp(12),dp(8),dp(12),dp(8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56));p.bottomMargin=dp(10);b.setLayoutParams(p);return b;}
  private EditText field(String hint,boolean multiline){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(white);e.setHintTextColor(Color.rgb(125,129,140));e.setTextSize(16);e.setPadding(dp(16),dp(12),dp(16),dp(12));e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(border));e.setBackgroundColor(panel);e.setInputType(multiline?(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES):(InputType.TYPE_CLASS_TEXT));e.setGravity(multiline?Gravity.TOP:Gravity.CENTER_VERTICAL);e.setSingleLine(!multiline);if(multiline)e.setMinLines(8);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,multiline?-2:dp(58));p.bottomMargin=dp(12);e.setLayoutParams(p);return e;}
  private void showLogin(){
    shell("");
    LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(22),dp(24),dp(22),dp(24));card.setBackgroundColor(panel);content.addView(card,new LinearLayout.LayoutParams(-1,-2));
    TextView brand=text("EROM",28,true,white);brand.setLetterSpacing(.12f);card.addView(brand);TextView sub=text("B O X",13,true,muted);sub.setLetterSpacing(.12f);card.addView(sub);
    TextView heading=text("Entre na sua conta",25,true,white);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(24);hp.bottomMargin=dp(8);card.addView(heading,hp);
    card.addView(text("Entre para acessar sua biblioteca local.",14,false,muted));
    card.addView(text("E-mail",13,false,muted));EditText email=field("voce@gmail.com",false);email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);card.addView(email);
    card.addView(text("Senha",13,false,muted));EditText pass=field("Mínimo de 8 caracteres",false);pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);card.addView(pass);
    Button enter=button("Entrar",true);card.addView(enter);Button forgot=button("Esqueci minha senha",false);card.addView(forgot);
    LinearLayout pair=new LinearLayout(this);pair.setOrientation(0);Button login2=button("Entrar",false);Button create=button("Criar conta",false);LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,dp(56),1);half.rightMargin=dp(6);pair.addView(login2,half);LinearLayout.LayoutParams half2=new LinearLayout.LayoutParams(0,dp(56),1);half2.leftMargin=dp(6);pair.addView(create,half2);card.addView(pair);
    TextView note=text("Esta versão funciona sem servidor. Sua conta e suas notas ficam somente neste telefone; não há sincronização online.",12,false,muted);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,-2);np.topMargin=dp(28);card.addView(note,np);
    Runnable doLogin=()->{String em=email.getText().toString().trim(),pw=pass.getText().toString();if(!em.contains("@")){toast("Digite um e-mail válido.");return;}if(pw.length()<8){toast("A senha precisa ter pelo menos 8 caracteres.");return;}String savedEmail=getPreferences(0).getString("local_email","");String savedPass=getPreferences(0).getString("local_pass","");if(getPreferences(0).getBoolean("local_account",false)){if(!em.equals(savedEmail)||!pw.equals(savedPass)){toast("Dados não conferem com a conta local deste telefone.");return;}}else{getPreferences(0).edit().putBoolean("local_account",true).putString("local_email",em).putString("local_pass",pw).apply();}hideKeyboard();showNotes();};
    enter.setOnClickListener(v->doLogin.run());login2.setOnClickListener(v->doLogin.run());create.setOnClickListener(v->{if(getPreferences(0).getBoolean("local_account",false)){toast("Já existe uma conta local neste telefone.");return;}doLogin.run();});forgot.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Conta local").setMessage("Não existe recuperação por e-mail sem servidor. Se esqueceu a senha, você pode apagar os dados do aplicativo nas configurações do Android; isso também apaga as notas locais.").setPositiveButton("OK",null).show());
  }
  private void showNotes(){shell("EROM BOX");content.addView(text("Suas notas, listas e ideias — tudo salvo neste telefone.",14,false,muted));searchField=field("Pesquisar notas…",false);searchField.setSingleLine(true);searchField.setText(filter);content.addView(searchField);searchField.setOnEditorActionListener((v,a,event)->{filter=searchField.getText().toString().trim().toLowerCase(Locale.ROOT);showNotes();return true;});Button add=button("+ Nova nota",true);content.addView(add);add.setOnClickListener(v->editNote(null));ArrayList<Note> shown=new ArrayList<>();for(Note n:notes)if((n.title+" "+n.body).toLowerCase(Locale.ROOT).contains(filter))shown.add(n);shown.sort((a,b)->Integer.compare(b.id,a.id));if(shown.isEmpty())content.addView(text(filter.isEmpty()?"Ainda não há notas. Toque em “Nova nota” para começar.":"Nenhuma nota encontrada.",15,false,muted));for(Note n:shown){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(12),dp(14),dp(8));card.setBackgroundColor(panel);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(10);content.addView(card,cp);card.addView(text(n.title.isEmpty()?"Sem título":n.title,18,true,white));String preview=n.body.replace("\n"," ");if(preview.length()>140)preview=preview.substring(0,140)+"…";card.addView(text(preview,14,false,muted));card.addView(text(n.updated,11,false,muted));Button open=button("Abrir / editar",false);card.addView(open);open.setOnClickListener(v->editNote(n));}Button logout=button("Sair da conta local",false);content.addView(logout);logout.setOnClickListener(v->showLogin());Button info=button("Sobre / armazenamento",false);content.addView(info);info.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("EROM BOX — Offline").setMessage("Aplicativo Android nativo, sem Chrome, Netlify, Supabase ou internet. A conta e as notas ficam neste telefone. Não há sincronização online.").setPositiveButton("OK",null).show());}
  private void editNote(Note n){shell(n==null?"Nova nota":"Editar nota");content.addView(text("Título",13,true,muted));titleField=field("Título da nota",false);content.addView(titleField);content.addView(text("Texto",13,true,muted));bodyField=field("Escreva aqui…",true);content.addView(bodyField);if(n!=null){titleField.setText(n.title);bodyField.setText(n.body);}Button save=button("Salvar nota",true);content.addView(save);save.setOnClickListener(v->{String t=titleField.getText().toString().trim(),b=bodyField.getText().toString();if(t.isEmpty()&&b.trim().isEmpty()){toast("Escreva algo antes de salvar.");return;}String now=java.text.DateFormat.getDateTimeInstance().format(new Date());if(n==null)notes.add(new Note(nextId++,t,b,now));else{n.title=t;n.body=b;n.updated=now;}persist();hideKeyboard();showNotes();toast("Nota salva neste telefone.");});Button cancel=button("Voltar sem salvar",false);content.addView(cancel);cancel.setOnClickListener(v->showNotes());if(n!=null){Button del=button("Excluir nota",false);content.addView(del);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Excluir nota?").setMessage("Esta ação não pode ser desfeita.").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(d,w)->{notes.remove(n);persist();showNotes();}).show());}}
  private void load(){String raw=getPreferences(0).getString("notes","[]");try{JSONArray a=new JSONArray(raw);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);Note n=new Note(o.optInt("id",nextId++),o.optString("title",""),o.optString("body",""),o.optString("updated",""));notes.add(n);nextId=Math.max(nextId,n.id+1);}}catch(Exception ignored){}}
  private void persist(){try{JSONArray a=new JSONArray();for(Note n:notes)a.put(new JSONObject().put("id",n.id).put("title",n.title).put("body",n.body).put("updated",n.updated));getPreferences(0).edit().putString("notes",a.toString()).apply();}catch(Exception e){toast("Não foi possível salvar a nota.");}}
  private void hideKeyboard(){try{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);}catch(Exception ignored){}}
  private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}